"""Generate crawlable source-linked evidence; the interactive app enhances it."""
from html import escape as e
import re
WARNING='ILLUSTRATIVE INPUTS - NOT MEASUREMENTS'
def content(data):
 sources={s['id']:s for s in data['sources']}
 def link(ident):
  s=sources[ident];return '<a href="'+e(s['url'],quote=True)+'">'+e(s['publisher']+' / '+ident)+'</a>'
 def table(headers,rows):
  return '<div class="table-wrap" tabindex="0" role="region" aria-label="Evidence table"><table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+cell+'</td>' for cell in row)+'</tr>' for row in rows)+'</tbody></table></div>'
 parts=['<div class="static-evidence"><noscript>JavaScript is disabled. Read the findings, source tables and limitations below. The interactive calculator requires JavaScript; downloadable evidence remains available.</noscript>', '<section id="overview"><div class="eyebrow">Open evidence atlas · v0.2</div><h1>AI has a water footprint.<br>Where, when, and which water?</h1><p>Computers produce heat. Cooling and electricity production can consume water in different places. Manufacturing is another boundary. There is no universal water-per-prompt figure and no verified global AI water total in this release.</p><p>Explore company reporting, regional context and conditional choices. Company figures are self-reported; selected metrics have limited assurance. ThirstyAI has not independently remeasured them.</p></section>']
 parts.append('<section id="companies"><h2>Company water disclosures</h2><p>Different periods, units and fleets: compare reporting, not company performance. Null is not zero.</p>'+table(['Company / metric','Value / unit','Period / geography / scope','Boundary / confidence','Source / locator / caveat'],[[e(c['company']+' / '+c['metric']),e(str(c['value']) if c['value'] is not None else 'Not extracted')+' '+e(c['unit']),e(c['period']+' / '+c['geography']+' / '+c['scope']),e(c['water_metric']+' / '+c['energy_denominator']+' / extraction '+c['confidence']),link(c['source_id'])+'<br>'+e(c['locator']+' / '+c['caveat'])] for c in data['companies']])+'</section>')
 parts.append('<section id="locations"><h2>Location context, not a hotspot ranking</h2><p>7 curated published location records; 5 US state-context matches; 0 verified exact facility/basin stress joins. No coordinates or water-supply basins are guessed. WRI administrative scores use a 1979–2019 modeled baseline. Unknown is not low risk.</p>'+table(['Published location / water','Regional context','Source trail'],[[e(r['company']+' '+r['location']+' / '+r['value']+' '+r['unit']+' / '+r['water_metric']+' / '+r['period']),e(r['stress_region']+' / '+r['stress_label']+' / score '+r['stress_score']+' dimensionless / '+r['stress_period']+' / geographic confidence '+r['match_confidence']),link(r['source_id'])+' '+e(r['locator'])+'<br>'+link(r['stress_source_id'])+' '+e(r['stress_locator'])] for r in data['overlay']])+'<p>WRI Aqueduct extract, CC BY 4.0. State proxy is not current facility stress or evidence of causal harm.</p></section>')
 parts.append('<section id="india"><h2>India groundwater: all users, not AI extraction</h2><p>36 state/UT observations from the 2025 CGWB assessment. Stage of extraction is annual extraction / annual extractable groundwater, not stored groundwater depleted. '+link('CGWB25')+'. '+link('WRIINDIA26')+' separately studies data-centre siting and stress; we do not recreate its commercial location inventory.</p><a href="data/india_groundwater_2025.csv">Download the attributed state table</a></section>')
 parts.append('<section id="lab"><h2>Decision lab</h2><strong>'+WARNING+'</strong><p>Hold useful IT work constant and compare direct consumptive WUE, PUE and electricity-related consumption. Manufacturing and local scarcity impacts are excluded. JavaScript enables the controls; these are hypothetical inputs, not measured company defaults.</p></section><section id="futures"><h2>Conditional futures to 2035</h2><strong>'+WARNING+'</strong><p>Demand growth and efficiency rates are assumptions. This is not a forecast of global AI water, drought or achieved savings.</p></section>')
 parts.append('<section id="evidence"><h2>Numerical claim register</h2>'+table(['Claim / value','Period / geography','Boundary / type / confidence','Source / locator / caveat'],[[e(c['title']+' / '+str(c['value'])+' '+c['unit']),e(c['period']+' / '+c['geography']),e(c['scope']+' / '+c['water_metric']+' / '+c['evidence_type']+' / '+c['confidence']),link(c['source_id'])+'<br>'+e(c['locator']+' / '+c['caveat'])] for c in data['claims']])+'<h2>Sources</h2>'+table(['Document','Scope / exact locator','Licence'],[[link(s['id'])+' '+e(s['title']),e(s['scope']+' / '+s['locator']),e(s['licence'])] for s in data['sources']])+'<p><a href="data/evidence.json">Download evidence and hashed provenance JSON</a></p></section>')
 parts.append('<section id="solutions"><h2>What can be done</h2><p>Companies: disclose comparable boundaries, test whole-system cooling choices, reduce energy per useful result, monitor seasonality and keep replenishment separate. Governments: request supply and drought plans and monitor discharge. Communities: ask for local supply and competing-use evidence. Individuals: choose adequate tools and share sourced claims with caveats; quantified personal water savings remain a gap.</p><h2>Limits</h2><p>No global AI water estimate, precise facility/basin overlay, independent community causal study, chip-water allocation, validated PBIX or confirmed Excel Desktop run. PostgreSQL execution status is recorded separately. Regional and company evidence do not establish local damage. The historical limitations file is not silently upgraded before author confirmation.</p><p>Independent portfolio research by Purushotman Mooper.</p></section></div>')
 return ''.join(parts)
def insert(html,data):
 return re.sub(r'<!-- STATIC_EVIDENCE_START -->.*?<!-- STATIC_EVIDENCE_END -->','<!-- STATIC_EVIDENCE_START -->'+content(data)+'<!-- STATIC_EVIDENCE_END -->',html,flags=re.S)
